# Install missing phuryn/pm-skills + mvanhorn/last30days-skill to tri-end global skills.
# Skips skills that already exist under ~/.cursor/skills.
param(
    [switch]$Force,
    [switch]$SkipLast30Days,
    [switch]$SkipPmSkillsUpdate
)

$ErrorActionPreference = 'Stop'
. (Join-Path $PSScriptRoot 'Write-Utf8NoBom.ps1')

$cursorSkills = Join-Path $env:USERPROFILE '.cursor\skills'
$claudeSkills = Join-Path $env:USERPROFILE '.claude\skills'
$codexSkills = Join-Path $env:USERPROFILE '.codex\skills'
$vendorDir = Join-Path $env:USERPROFILE '.ai-workspace\vendor\phuryn-pm-skills'

function Remove-LinkOrDir {
    param([string]$Path)
    if (-not (Test-Path -LiteralPath $Path)) { return }
    $item = Get-Item -LiteralPath $Path -Force
    if ($item.LinkType -in @('Junction', 'SymbolicLink')) {
        Remove-Item -LiteralPath $Path -Force
    }
    elseif ($item.PSIsContainer) {
        Remove-Item -LiteralPath $Path -Recurse -Force
    }
    else {
        Remove-Item -LiteralPath $Path -Force
    }
}

function Copy-SkillToGlobal {
    param(
        [string]$SourceDir,
        [string]$SkillName
    )
    if (-not (Test-Path (Join-Path $SourceDir 'SKILL.md'))) {
        Write-Warning "Skip missing SKILL.md: $SourceDir"
        return 'missing'
    }
    $dest = Join-Path $cursorSkills $SkillName
    if ((Test-Path $dest) -and -not $Force) {
        Write-Host "SKIP exists: $SkillName"
        return 'skipped'
    }
    if (Test-Path $dest) { Remove-LinkOrDir -Path $dest }
    Copy-Item -LiteralPath $SourceDir -Destination $dest -Recurse -Force
    Write-Host "INSTALLED cursor: $SkillName"
    return 'installed'
}

function Mirror-SkillJunction {
    param([string]$SkillName)
    $src = Join-Path $cursorSkills $SkillName
    if (-not (Test-Path $src)) { return }
    $resolved = (Resolve-Path -LiteralPath $src).Path
    foreach ($root in @($claudeSkills, $codexSkills)) {
        if (-not (Test-Path $root)) { New-Item -ItemType Directory -Path $root -Force | Out-Null }
        $dest = Join-Path $root $SkillName
        Remove-LinkOrDir -Path $dest
        New-Item -ItemType Junction -Path $dest -Target $resolved | Out-Null
        Write-Host "JUNCTION $root\$SkillName -> $resolved"
    }
}

foreach ($root in @($cursorSkills, $claudeSkills, $codexSkills)) {
    if (-not (Test-Path $root)) { New-Item -ItemType Directory -Path $root -Force | Out-Null }
}

$installed = @()
$skipped = @()
$missing = @()

if (-not $SkipPmSkillsUpdate) {
    if (-not (Test-Path $vendorDir)) {
        Write-Host "Cloning phuryn/pm-skills -> $vendorDir"
        git clone --depth 1 https://github.com/phuryn/pm-skills.git $vendorDir
    }
    else {
        Write-Host "Updating phuryn/pm-skills vendor"
        Push-Location $vendorDir
        git pull --ff-only
        Pop-Location
    }

    $skillFiles = Get-ChildItem -Path $vendorDir -Filter 'SKILL.md' -Recurse -File |
        Where-Object { $_.FullName -match '\\skills\\' }

    foreach ($file in $skillFiles) {
        $skillName = Split-Path $file.DirectoryName -Leaf
        $result = Copy-SkillToGlobal -SourceDir $file.DirectoryName -SkillName $skillName
        switch ($result) {
            'installed' { $installed += $skillName; Mirror-SkillJunction -SkillName $skillName }
            'skipped' { $skipped += $skillName }
            default { $missing += $skillName }
        }
    }
}

if (-not $SkipLast30Days) {
    Write-Host 'Installing last30days via npx skills (cursor, codex, claude-code)...'
    $npxArgs = @(
        'skills', 'add', 'mvanhorn/last30days-skill', '-g',
        '-a', 'cursor', '-a', 'codex', '-a', 'claude-code', '-y'
    )
    & npx @npxArgs
    if ($LASTEXITCODE -ne 0) {
        Write-Warning "npx skills add failed with exit $LASTEXITCODE — trying cursor-only"
        & npx skills add mvanhorn/last30days-skill -g -a cursor -y
    }
    if (Test-Path (Join-Path $cursorSkills 'last30days')) {
        Mirror-SkillJunction -SkillName 'last30days'
        if ($installed -notcontains 'last30days') { $installed += 'last30days' }
    }
    else {
        Write-Warning 'last30days not found under ~/.cursor/skills after npx install'
    }
}

$scanScript = Join-Path $PSScriptRoot 'scan-global-skills.ps1'
if (Test-Path $scanScript) {
    & $scanScript -OutputFormat Plain | Out-Null
    Write-Host 'Rescanned global skills index'
}

Write-Host ''
Write-Host "Done. Installed/updated: $($installed.Count); skipped existing: $($skipped.Count)"
if ($installed.Count -gt 0) {
    Write-Host 'New/updated skills:'
    $installed | Sort-Object | ForEach-Object { Write-Host "  - $_" }
}

